const flags=window.COURSELATCH_RUNTIME||{};
const checks=[
 ['PayPal sandbox',flags.paypal?'Configured · run a capture':'Credentials still needed'],
 ['Course access',flags.courseAccess?'Separate service configured':'Demo service only'],
 ['AI specialists',flags.ai?'Model configured · inspect a case':'Scripted sample only'],
 ['Render Workflows',flags.workflows?'Configured · inspect a run':'Not configured yet']
];
const list=document.querySelector('#judge-readiness-list');
for(const [name,status] of checks){const item=document.createElement('div');const title=document.createElement('strong');const detail=document.createElement('span');title.textContent=name;detail.textContent=status;item.append(title,detail);list.append(item);}
const paths=document.querySelector('.paths');
if(paths){paths.className='judge-route';paths.setAttribute('aria-label','Two-minute judge route');paths.innerHTML=`<div class="judge-route-intro"><span class="eyebrow">THE JUDGE ROUTE / ABOUT TWO MINUTES</span><h2>Follow one customer from locked out to checked outcome.</h2><p>Start with the guided sample, then inspect a separate merchant case. The sample shows the product experience; a sandbox checkout is a separate connected test.</p><a class="button route-start" href="story.html">Start with Maya’s purchase →</a></div><ol><li><b>01</b><div><strong>See the problem</strong><span>Watch Maya pay and find the lesson still locked.</span><a href="story.html">Open the guided sample ↗</a></div></li><li><b>02</b><div><strong>Inspect the decision</strong><span>Open a server-backed merchant case, evidence map, four findings, and exact approval.</span><a href="focus.html">Open merchant desk ↗</a></div></li><li><b>03</b><div><strong>Check the result</strong><span>Review the access proof and download the run report. Sample and connected evidence are labeled.</span><a href="focus.html">Inspect the recovery receipt ↗</a></div></li></ol>`;const connected=document.createElement('aside');connected.className='judge-connected';connected.innerHTML=`<div><span class="eyebrow">CONNECTED SANDBOX RUN</span><h2>Ready to test PayPal?</h2><p>${flags.paypal?'PayPal credentials are configured. Create a new sandbox case, complete checkout, and inspect the run report before claiming connected proof.':'PayPal sandbox credentials are not configured on this deployment yet. The guided sample and server-backed case review remain available.'}</p></div><a href="focus.html?screen=connections">Open the connection checklist ↗</a>`;paths.after(connected);}
